import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it (a clerk unless made a steward) and its clerk
 * limit, the most a clerk may settle a claim for (none when null), and its floor, the least a claim's
 * live due can be, and its cap, the most a person's due-total can be (none when null), and its terms, how many business days after its date a claim is due by (each grade may have its own
 * terms in their place), and its late percent, the
 * percent of its figure an overdue claim's due gains for every full 30 days it is overdue, and its policy
 * date, which decides how a claim's live figures round (the sheet's today when none is set), and its
 * period numbering from, the date from which a claim opened is numbered within its period (off when null),
 * and its proof threshold, above which a claim's due needs a proof before it is settled (none when null; each grade may
 * have its own in its place),
 * and its grace days, how many days after its to-date an open period is closed when the sheet's today
 * is changed (off when null), and each grade's grace days, how many days past its due-by a claim of the
 * grade is overdue from (none when null).
 * The settings that carry a figure (the clerk limit, the floor, the cap, the terms, the late percent, the proof threshold and the grades' grace days)
 * are dated: each value is recorded from a date (see {@link DatedSettings}); the policy date, the
 * period numbering from and the grace days are not. Its permission matrix, also not dated, gives for each {@link Action}
 * the roles that may take it; a blank entry keeps the action's standing rule. */
@Service
public class SettingsService {

    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SheetRoleRepository roles;
    private final SheetSettingRepository settings;
    private final SheetPermissionRepository permissions;
    private final DatedSettings dated;
    private final RollupService rollup;
    private final DelegationService delegations;
    private final Audit audit;

    public SettingsService(SheetRepository sheets, SheetRoleRepository roles, SheetSettingRepository settings,
            SheetPermissionRepository permissions, DatedSettings dated, RollupService rollup,
            DelegationService delegations, Audit audit) {
        this.delegations = delegations;
        this.permissions = permissions;
        this.sheets = sheets;
        this.roles = roles;
        this.settings = settings;
        this.dated = dated;

    /** Set the sheet's period numbering from; null turns it off. Only the claims opened from then on follow it. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setPeriodNumberingFrom(from);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=period-numbering-from",
                "value=" + (from == null ? "" : from.toString()));
        return sheet;
    }

    /** The sheet's grace days; null when they are off. */
    @Transactional(readOnly = true)
    public Integer graceDays(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getGraceDays();
    }

    /** Set the sheet's grace days; null turns them off. They take effect when the sheet's today is next changed. */
    @Transactional
    public Sheet setGraceDays(String sheetId, String by, Integer graceDays) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setGraceDays(graceDays);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=grace-days", "value=" + (graceDays == null ? "" : graceDays));
        return sheet;
    }

    /** The sheet's entry date; null when it is off. */
    @Transactional(readOnly = true)
    public LocalDate entryDate(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getEntryDate();
    }

    /** Set the sheet's entry date; null turns it off. Only the claims added or edited from then on follow it. */
    @Transactional
    public Sheet setEntryDate(String sheetId, String by, LocalDate entryDate) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        sheet.setEntryDate(entryDate);
        sheets.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=entry-date",
                "value=" + (entryDate == null ? "" : entryDate.toString()));
        return sheet;
    }

    /** The id of the sheet's parent; null when there is none. */
    @Transactional(readOnly = true)
    public String parent(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getParentId();
    }

/** A sheet's settings: its roles, its clerk limit, its floor, its cap, its terms, its late percent (each dated: saved with a from-date, the sheet's today when blank), its policy date and its period numbering from. The signed-in user's name travels in the
 * {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class SettingsController {

    /** A user name and the role it has on the sheet (clerk or steward). */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().name().toLowerCase());
        }
    }

    /** The sheet's settings; the floor is sent as text with two decimals; the cap is sent as text with two decimals, null when there is none; the clerk limit is sent as text with two decimals, null when there is none; the terms in days; the grades' own terms in days, by grade (a grade not in it uses the sheet's terms); the late percent as text with two decimals; the policy date as set, null when it is the sheet's today; the period numbering from, null when it is off. The clerk limit, the floor, the cap, the terms, the grades' own terms and the late percent are those in force on the sheet's today; every floor, late percent and cap recorded, each from its date, oldest first, follow (a claim's floor and late percent are those in force on its date; a cap recorded as none is null); the proof threshold in force on the sheet's today, as text with two decimals, null when there is none, follows; then the permission matrix as set, the roles that may take each action by action (open, settle, void, reassign, close, reopen), blank for its standing rule; then the grace days, null when they are off; then the note threshold in force on the sheet's today, as text with two decimals, null when there is none; then the entry date, null when it is off; then the grades' grace days in force on the sheet's today, in days, by grade (a grade not in it has none); then every grace recorded for each grade, each from its date, oldest first, by grade (a grace recorded as none is null); then the grades' own proof thresholds in force on the sheet's today, as text with two decimals, by grade (a grade not in it uses the sheet's); then the pot, as text with two decimals, null when there is none; then the id of the parent sheet, null when there is none. */
    public record SettingsView(String clerkLimit, String floor, String cap, int terms, Map<String, Integer> gradeTerms, String latePct, LocalDate policyDate,
            List<RoleView> roles, LocalDate periodNumberingFrom, List<DatedView> floors, List<DatedView> latePcts, List<DatedView> caps,
            String proofThreshold, Map<String, String> permissions, Integer graceDays, String noteThreshold, LocalDate entryDate,
            Map<String, Integer> gradeGraces, Map<String, List<DatedView>> graces, Map<String, String> gradeProofThresholds, String pot, String parent) {
    }

    /** The roles that may take an action: a comma separated list of clerk and steward; blank or null for
     * the action's standing rule. */
    public record PermissionRequest(@Size(max = 100) @Pattern(regexp = "\\s*((clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?") String value) {
        String rolesValue() {
            return value == null ? "" : value.replaceAll("\\s", "");
        }
    }

    /** A value of a dated setting, as text, and the date it is recorded from. */
    public record DatedView(LocalDate from, String value) {
        static DatedView of(SheetSetting setting) {
            return new DatedView(setting.getFrom(), setting.getValue());
        }
    }

    /** A role: clerk, steward or viewer. */
    public record RoleRequest(@NotNull @Pattern(regexp = "\\s*(clerk|steward|viewer)\\s*") String role) {
        Role roleValue() {
            return Role.valueOf(role.trim().toUpperCase());
        }
    }

    /** A clerk limit: 0.00 or more, with up to two decimals; blank or null for no limit. */
    public record ClerkLimitRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal limitValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A floor: 0.00 or more, with up to two decimals. */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal floorValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A cap: 0.00 or more, with up to two decimals; blank or null for no cap. */
    public record CapRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal capValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A proof or note threshold: 0.00 or more, with up to two decimals; blank or null for none. */
    public record ProofThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal thresholdValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** Terms: a whole number of business days, 0 or more. */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,4}\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        int termsValue() {
            return Integer.parseInt(value.trim());
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A grade's own terms: a whole number of business days, 0 or more; blank or null to use the sheet's terms. */
    public record GradeTermsRequest(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        Integer termsValue() {
            return value == null || value.isBlank() ? null : Integer.parseInt(value.trim());
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A grade's grace days: a whole number of days, 0 or more; blank or null for none. */
    public record GradeGraceRequest(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        Integer daysValue() {
            return value == null || value.isBlank() ? null : Integer.parseInt(value.trim());
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A late percent: 0.00 or more, with up to two decimals. */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String from) {
        BigDecimal latePctValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }

        LocalDate fromValue() {
            return fromOf(from);
        }
    }

    /** A from-date (YYYY-MM-DD); null when blank or null, for the sheet's today. */
    private static LocalDate fromOf(String from) {
        return from == null || from.isBlank() ? null : LocalDate.parse(from.trim());
    }

    /** A policy date (YYYY-MM-DD); blank or null for the sheet's today. */
    public record PolicyDateRequest(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {
        LocalDate dateValue() {
            return value == null || value.isBlank() ? null : LocalDate.parse(value.trim());
        }
    }

    /** A period numbering from date (YYYY-MM-DD); blank or null turns it off. */
    public record PeriodNumberingFromRequest(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {
        LocalDate dateValue() {
            return value == null || value.isBlank() ? null : LocalDate.parse(value.trim());
        }
    }

    /** An entry date (YYYY-MM-DD); blank or null turns it off. */
    public record EntryDateRequest(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {
        LocalDate dateValue() {
            return value == null || value.isBlank() ? null : LocalDate.parse(value.trim());
        }
    }

    /** Grace days, a whole number of days; blank or null turns them off. */
    public record GraceDaysRequest(@Pattern(regexp = "\\s*(\\d{1,4})?\\s*") String value) {
        Integer daysValue() {
            return value == null || value.isBlank() ? null : Integer.valueOf(value.trim());
        }
    }

    /** A pot: 0.00 or more, with up to two decimals; blank or null for none. */
    public record PotRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String value) {
        BigDecimal potValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** A parent sheet's id; blank or null for none. */
    public record ParentRequest(@Size(max = 100) String value) {
        String parentValue() {
            return value == null || value.isBlank() ? null : value.trim();
        }
    }

    private final SettingsService service;

    private final SheetHistory history;

    public SettingsController(SettingsService service, SheetHistory history) {
        this.service = service;
        this.history = history;
    }

    @GetMapping("/settings")
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        String sheet = sheetId.trim();
        if (asOf != null) return viewOf(history.read(sheet, asOf));
        return new SettingsView(text(service.clerkLimit(sheet)), text(service.floor(sheet)),
                text(service.cap(sheet)), service.terms(sheet),
                service.gradeTerms(sheet),
                text(service.latePct(sheet)), service.policyDate(sheet), service.roles(sheet).stream().map(RoleView::of).toList(),
                service.periodNumberingFrom(sheet),
                service.history(sheet, DatedSettings.FLOOR).stream().map(DatedView::of).toList(),
                service.history(sheet, DatedSettings.LATE_PCT).stream().map(DatedView::of).toList(),
                service.history(sheet, DatedSettings.CAP).stream().map(DatedView::of).toList(),
                text(service.proofThreshold(sheet)), permissionsOf(service.permissions(sheet)), service.graceDays(sheet),
                text(service.noteThreshold(sheet)), service.entryDate(sheet), service.gradeGraces(sheet),
                gracesOf(grade -> service.history(sheet, DatedSettings.gradeGraceKey(grade))),
                textOf(service.gradeProofThresholds(sheet)), text(service.pot(sheet)), service.parent(sheet));
    }

    /** Every grace recorded for each grade, oldest first, by grade. */
    private static Map<String, List<DatedView>> gracesOf(Function<String, List<SheetSetting>> history) {
        Map<String, List<DatedView>> graces = new LinkedHashMap<>();
        for (String grade : List.of("A", "B", "C")) {
            graces.put(grade, history.apply(grade).stream().map(DatedView::of).toList());
        }
        return graces;
    }

    /** The settings as they stood on the sheet as of a date, that date standing in for its today. */
    private static SettingsView viewOf(SheetAsOf then) {
        LocalDate today = then.today();
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : List.of("A", "B", "C")) {
            then.valueOn(DatedSettings.gradeTermsKey(grade), today).map(Integer::valueOf)
                    .ifPresent(own -> gradeTerms.put(grade, own));
        }
        Map<String, Integer> gradeGraces = new LinkedHashMap<>();
        for (String grade : List.of("A", "B", "C")) {
            Integer grace = then.graceOn(grade, today);
            if (grace != null) gradeGraces.put(grade, grace);
        }
        Map<String, BigDecimal> gradeProofThresholds = new LinkedHashMap<>();
        for (String grade : List.of("A", "B", "C")) {
            then.valueOn(DatedSettings.gradeProofThresholdKey(grade), today).map(BigDecimal::new)
                    .ifPresent(own -> gradeProofThresholds.put(grade, own));
        }
        Map<Action, String> matrix = new EnumMap<>(Action.class);
        for (Action action : Action.values()) matrix.put(action, "");
        for (SheetPermission set : then.permissions()) matrix.put(set.getAction(), set.getRoles());
        return new SettingsView(
                text(then.valueOn(DatedSettings.CLERK_LIMIT, today).map(BigDecimal::new).orElse(null)),
                text(then.floorOn(today)), text(then.cap()),
                then.valueOn(DatedSettings.TERMS, today).map(Integer::valueOf).orElse(DatedSettings.TERMS_START),
                gradeTerms, text(then.latePctOn(today)), then.policyDate(),
                then.roles().stream().map(RoleView::of).toList(), then.periodNumberingFrom(),
                then.history(DatedSettings.FLOOR).stream().map(DatedView::of).toList(),
                then.history(DatedSettings.LATE_PCT).stream().map(DatedView::of).toList(),
                then.history(DatedSettings.CAP).stream().map(DatedView::of).toList(),
                text(then.valueOn(DatedSettings.PROOF_THRESHOLD, today).map(BigDecimal::new).orElse(null)),
                permissionsOf(matrix), then.graceDays(),
                text(then.valueOn(DatedSettings.NOTE_THRESHOLD, today).map(BigDecimal::new).orElse(null)),
                then.entryDate(), gradeGraces,
                gracesOf(grade -> then.history(DatedSettings.gradeGraceKey(grade))),
                textOf(gradeProofThresholds), text(then.pot()), then.parentId());
    }

